public class Main {
    /** 遵守双亲委派：只重写 findClass */
    static class DelegatingLoader extends ClassLoader {
        DelegatingLoader(ClassLoader parent) { super(parent); }
        @Override protected Class<?> findClass(String name) throws ClassNotFoundException {
            System.out.println("    findClass(" + name + ")");
            throw new ClassNotFoundException(name);
        }
    }
    /** 打破双亲委派：重写 loadClass，先自己找再委派 */
    static class BreakingLoader extends ClassLoader {
        final String tag;
        BreakingLoader(String tag, ClassLoader parent) { super(parent); this.tag = tag; }
        @Override protected Class<?> loadClass(String name, boolean resolve) throws ClassNotFoundException {
            synchronized (getClassLoadingLock(name)) {
                Class<?> c = findLoadedClass(name);
                if (c == null) {
                    System.out.println("    " + tag + " tries first: " + name);
                    try { c = findClass(name); } catch (ClassNotFoundException ignored) { }
                    if (c == null) c = super.loadClass(name, resolve);
                }
                if (resolve) resolveClass(c);
                return c;
            }
        }
        @Override protected Class<?> findClass(String name) throws ClassNotFoundException { return null; }
    }

    public static void main(String[] args) throws Exception {
        ClassLoader app = Main.class.getClassLoader();
        System.out.println("=== delegation chain (app -> ... -> bootstrap) ===");
        int level = 0;
        for (ClassLoader cl = app; cl != null; cl = cl.getParent()) {
            ClassLoader par = cl.getParent();
            System.out.println("    level " + (level++) + ": " + cl.getClass().getName()
                    + "   parent=" + (par == null ? "<bootstrap, native>" : par.getClass().getSimpleName()));
        }
        System.out.println("    PlatformClassLoader.getParent() == null (bootstrap) : "
                + (app.getParent().getParent() == null));

        System.out.println("=== delegating loader: java.lang.String resolved by bootstrap ===");
        Class<?> s = new DelegatingLoader(app).loadClass("java.lang.String");
        System.out.println("    same Class object as String.class : " + (s == String.class));

        System.out.println("=== breaking loader: tries itself first, then delegates ===");
        ClassLoader bl = new BreakingLoader("Breaking", app);
        Class<?> s2 = bl.loadClass("java.lang.String");
        System.out.println("    got java.lang.String : " + (s2 != null) + ", same as bootstrap : " + (s2 == String.class));

        System.out.println("=== class identity = loader + FQN ===");
        ClassLoader b1 = new BreakingLoader("B1", app), b2 = new BreakingLoader("B2", app);
        Class<?> c1 = b1.loadClass("java.lang.String");
        Class<?> c2 = b2.loadClass("java.lang.String");
        System.out.println("    two loaders, same FQN, same Class object : " + (c1 == c2));
        System.out.println("    reason: bootstrap already loaded it, both delegated up");
    }
}
